import { Alert, Card, Group, Progress, Stack, Text } from "@mantine/core";
import { useWidgetQuery } from "@homarr/widget-sdk";
interface MetricData { usedPercent: number; }
interface MetricProps { title: string; query: ReturnType<typeof useWidgetQuery<MetricData>>; }
function Metric({ title, query }: MetricProps) {
  return <Card withBorder><Stack gap="xs"><Text fw={600}>{title}</Text>
    {query.isPending && <Text c="dimmed">Loading…</Text>}
    {query.error && <Alert color="orange">{query.error.message}</Alert>}
    {query.data && <><Group justify="space-between"><Text>Used</Text><Text>{query.data.usedPercent}%</Text></Group><Progress value={query.data.usedPercent} /></>}
  </Stack></Card>;
}
export default function LocalMetrics() {
  const memory = useWidgetQuery<MetricData>("memory", {}, {refetchInterval: 10000});
  const storage = useWidgetQuery<MetricData>("storage", {}, {refetchInterval: 10000});
  return <Stack p="md"><Metric title="Memory" query={memory} /><Metric title="Storage" query={storage} /></Stack>;
}

