import { freemem, totalmem } from "node:os";
import { statfs } from "node:fs/promises";
import { defineWidgetServer } from "@homarr/widget-sdk/server";
export default defineWidgetServer({
  memory: () => ({usedPercent: Math.round(100 * (1 - freemem() / totalmem()))}),
  storage: async () => {const value = await statfs(process.cwd()); return {usedPercent: Math.round(100 * (1 - value.bavail / value.blocks))};},
});
